begin;
create extension if not exists pgtap with schema extensions;
set search_path = public,extensions;
select no_plan();
create temp table test_state(key text primary key,value jsonb);
grant select,insert,update on test_state to authenticated;

set local role anon;
select set_config('request.jwt.claims','{}',true);
select throws_ok('select * from public.businesses','42501',null,'anonymous cannot read tenant tables');
select throws_ok($$select public.bootstrap_business(gen_random_uuid(),'Bad','Bad')$$,'42501',null,'publishable key alone cannot bootstrap');
select throws_ok('select public.get_workspace_context()','42501',null,'anonymous cannot call context RPC');
select is((select count(*) from storage.objects where bucket_id='client-files'),0::bigint,'anonymous cannot see private Storage metadata');
reset role;

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000008","user_metadata":{"role":"owner","business_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1"}}',true);
select is((select count(*) from public.businesses),0::bigint,'non-member metadata grants no business reads');
select is(public.get_workspace_context(),'[]'::jsonb,'non-member gets an empty context');
select throws_ok($$insert into public.business_members(business_id,user_id,role_code,scope_mode) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',auth.uid(),'owner','all_locations')$$,'42501',null,'membership self-insert denied');
select throws_ok($$update public.profiles set id='11111111-1111-4111-8111-000000000001' where id=auth.uid()$$,'42501',null,'profile identity column is not editable');
select lives_ok($$update public.profiles set display_name='Synthetic outsider',locale='ar' where id=auth.uid()$$,'own non-authoritative profile fields are editable');
select throws_ok($$select app_private.audit('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','fake',gen_random_uuid())$$,'42501',null,'internal audit helper cannot be invoked by a user');
select throws_ok($$select public.authorize_workspace('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','members.manage')$$,'42501',null,'non-member direct authorization RPC denied');

select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000001"}',true);
select is((select count(*) from public.businesses),1::bigint,'owner sees only business A');
select is((select count(*) from public.locations),2::bigint,'owner has all A locations');
select is((select count(*) from public.staff_members),2::bigint,'owner sees independent staff, including no-login staff');
select is((select count(*) from public.staff_identity_links),1::bigint,'staff can exist without identity links');
select throws_ok($$update public.business_members set role_code='owner' where user_id='11111111-1111-4111-8111-000000000003'$$,'42501',null,'direct role escalation denied');
select throws_ok($$update public.businesses set status='active',owner_user_id='11111111-1111-4111-8111-000000000003'$$,'42501',null,'direct owner/status mutation denied');
select throws_ok($$delete from public.business_members where user_id=auth.uid()$$,'42501',null,'direct last-owner deletion denied');
select throws_ok($$select public.set_member_access('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',auth.uid(),'manager','all_locations','{}',true)$$,'23514',null,'last owner cannot demote or revoke self');
select throws_ok($$select public.set_member_access('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','11111111-1111-4111-8111-000000000003','owner','all_locations','{}',true)$$,'22023',null,'membership command cannot manufacture another owner');
select throws_ok($$select public.set_member_access('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','11111111-1111-4111-8111-000000000003','manager','selected_locations',array['b1000000-0000-4000-8000-000000000001'::uuid],true)$$,'22023',null,'owner RPC rejects cross-business location scope');
select throws_ok($$insert into public.audit_events(business_id,actor_user_id,action,object_id) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',auth.uid(),'spoof',gen_random_uuid())$$,'42501',null,'client cannot forge audit actor/events');
select throws_ok($$select public.issue_invitation('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','invitee@miznora.example.test','manager','all_locations','{}')$$,'42501',null,'owner A cannot issue invitations into B');
select throws_ok($$select * from app_private.invitations$$,'42501',null,'invite token hashes are private');

select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000003"}',true);
select is((select count(*) from public.locations),1::bigint,'manager is restricted to granted location');
select is((select count(*) from storage.objects where bucket_id='client-files'),1::bigint,'private Storage read checks location and membership');
select throws_ok($$select public.register_file('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','a1000000-0000-4000-8000-000000000002','pdf',false)$$,'42501',null,'manager cannot register a file in an ungranted location');
select throws_ok($$select public.issue_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','invitee@miznora.example.test','manager','all_locations','{}')$$,'42501',null,'manager cannot grant membership');
select throws_ok($$insert into storage.objects(bucket_id,name) values('client-files','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/guessed.pdf')$$,'42501',null,'guessed tenant path without registry entry is not upload authority');
select lives_ok($$insert into pg_temp.test_state values('file',public.register_file('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','a1000000-0000-4000-8000-000000000001','pdf',false))$$,'authorized scoped file registration works');
select lives_ok($$insert into storage.objects(bucket_id,name) select value->>'bucket',value->>'path' from pg_temp.test_state where key='file'$$,'registered private upload metadata is authorized');
select throws_ok($$update storage.objects set name='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1/forged.pdf' where name=(select value->>'path' from pg_temp.test_state where key='file')$$,'42501',null,'Storage update WITH CHECK rejects reassignment');

select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000004"}',true);
select is((select count(*) from storage.objects where bucket_id='client-files'),0::bigint,'receptionist cannot read private workspace documents');
select throws_ok($$select public.register_file('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','a1000000-0000-4000-8000-000000000001','pdf',false)$$,'42501',null,'receptionist cannot upload private files');
select is((select count(*) from public.audit_events),0::bigint,'receptionist cannot read audit events');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000005"}',true);
select is((select count(*) from public.staff_members),1::bigint,'professional sees only linked staff identity');
select is((select count(*) from public.staff_identity_links),1::bigint,'professional sees own link only');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000007"}',true);
select is(jsonb_array_length(public.get_workspace_context()),2,'shared user has two independently scoped businesses');
select is((select count(*) from public.locations),2::bigint,'shared user sees only one location in each business');
select is((select count(*) from storage.objects where bucket_id='client-files'),0::bigint,'permissions are not unioned across business roles');

select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000001"}',true);
select lives_ok($$select public.set_member_access('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','11111111-1111-4111-8111-000000000003','manager','selected_locations',array['a1000000-0000-4000-8000-000000000002'::uuid],true)$$,'owner changes authoritative location scope');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000003"}',true);
select is((select count(*) from public.locations where id='a1000000-0000-4000-8000-000000000001'),0::bigint,'old location revoked with unchanged session claims');
select is((select count(*) from storage.objects where name=(select value->>'path' from pg_temp.test_state where key='file')),0::bigint,'file access follows location revocation immediately');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000001"}',true);
select lives_ok($$select public.set_member_access('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','11111111-1111-4111-8111-000000000003','manager','all_locations','{}',false)$$,'owner revokes membership');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000003","user_metadata":{"role":"owner"}}',true);
select is((select count(*) from public.businesses),0::bigint,'revoked member cannot read with an otherwise unchanged session');
select throws_ok($$select public.authorize_workspace('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','files.write','a1000000-0000-4000-8000-000000000001')$$,'42501',null,'revoked role cannot invoke authorized commands');

select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000001"}',true);
select lives_ok($$insert into pg_temp.test_state values('invite',public.issue_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','invitee@miznora.example.test','receptionist','selected_locations',array['a1000000-0000-4000-8000-000000000001'::uuid]))$$,'owner issues a scoped invitation');
select throws_ok($$select public.issue_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','invitee@miznora.example.test','owner','all_locations','{}')$$,'22023',null,'invitation cannot create owner role');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000008"}',true);
select throws_ok($$select public.accept_invitation((select value->>'token' from pg_temp.test_state where key='invite'))$$,'42501',null,'wrong verified identity cannot accept someone else’s invitation');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000009"}',true);
select is(public.accept_invitation((select value->>'token' from pg_temp.test_state where key='invite')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'::uuid,'intended verified invitee accepts');
select is(public.accept_invitation((select value->>'token' from pg_temp.test_state where key='invite')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'::uuid,'duplicate invitation acceptance is idempotent');
select is((select count(*) from public.business_members where user_id=auth.uid()),1::bigint,'acceptance creates one membership');
select is((select count(*) from public.locations),1::bigint,'accepted invitation grants only its controlled scope');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000001"}',true);
select lives_ok($$insert into pg_temp.test_state values('revoked',public.issue_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','outsider@miznora.example.test','manager','all_locations','{}'))$$,'second synthetic invite issued');
select lives_ok($$select public.revoke_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',(select (value->>'id')::uuid from pg_temp.test_state where key='revoked'))$$,'owner revokes invitation');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000008"}',true);
select throws_ok($$select public.accept_invitation((select value->>'token' from pg_temp.test_state where key='revoked'))$$,'42501',null,'revoked invitation cannot be accepted');

select lives_ok($$insert into pg_temp.test_state values('bootstrap',to_jsonb(public.bootstrap_business('44444444-4444-4444-8444-000000000001','Synthetic new business','Muscat')))$$,'verified non-member can bootstrap a new business');
select is(to_jsonb(public.bootstrap_business('44444444-4444-4444-8444-000000000001','Synthetic new business','Muscat')),(select value from pg_temp.test_state where key='bootstrap'),'bootstrap retry returns the same business');
select throws_ok($$select public.bootstrap_business('44444444-4444-4444-8444-000000000001','Different name','Muscat')$$,'22023',null,'bootstrap key reuse with changed payload rejected');
select throws_ok($$select public.bootstrap_business('44444444-4444-4444-8444-000000000002','Another business','Muscat')$$,'22023',null,'first-business bootstrap cannot create unlimited businesses');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000010"}',true);
select throws_ok($$select public.bootstrap_business(gen_random_uuid(),'Unverified','Muscat')$$,'42501',null,'unverified identity cannot bootstrap');
select is((select count(*) from public.businesses),0::bigint,'unverified identity has no workspace authority');

reset role;
select throws_ok($$insert into public.member_location_scopes values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','11111111-1111-4111-8111-000000000007','b1000000-0000-4000-8000-000000000001')$$,'23503',null,'composite FK rejects a cross-business child even for a trusted SQL writer');
select throws_ok($$update public.locations set business_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1' where id='a1000000-0000-4000-8000-000000000001'$$,'42501',null,'ownership immutability trigger rejects business reassignment');
select throws_ok($$update public.audit_events set actor_user_id='11111111-1111-4111-8111-000000000002'$$,'42501',null,'audit UPDATE rejected even for a trusted writer');
select throws_ok($$delete from public.audit_events$$,'42501',null,'audit DELETE rejected');
select is((select count(*) from app_private.invitations i join pg_temp.test_state t on t.key='invite' where i.token_hash=t.value->>'token'),0::bigint,'invitation stores only a hash, never the returned bearer token');
select is((select count(*) from public.audit_events where action='invitation.accepted' and actor_user_id='11111111-1111-4111-8111-000000000009'),1::bigint,'audit actor is server-attributed and acceptance does not duplicate its event');
select throws_ok($$delete from public.business_members where business_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1' and role_code='owner'; set constraints all immediate$$,'23514',null,'deferred invariant prevents removing the last canonical owner');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000001"}',true);
select throws_ok($$select public.transfer_ownership('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','11111111-1111-4111-8111-000000000002')$$,'42501',null,'ownership cannot be transferred to a non-member');
select lives_ok($$select public.transfer_ownership('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','11111111-1111-4111-8111-000000000009')$$,'ownership transfer to an accepted verified member is atomic');
select throws_ok($$select public.list_business_members('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')$$,'42501',null,'previous owner loses membership-management authority');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000009"}',true);
select is((select count(*) from public.locations),2::bigint,'new owner gains all locations without a staff assignment');
select lives_ok($$select public.list_business_members('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')$$,'new owner has controlled membership access');
reset role;
update public.businesses set status='suspended' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000009"}',true);
select is((select count(*) from public.businesses),1::bigint,'suspended business retains owner read access');
select throws_ok($$select public.issue_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','outsider@miznora.example.test','manager','all_locations','{}')$$,'42501',null,'suspension denies ordinary owner writes');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000004"}',true);
select is((select count(*) from public.businesses),0::bigint,'suspended business is not exposed to ordinary members');
reset role;
set constraints all immediate;
-- Separate intentionally public marketing objects from private workspace files.
set constraints all deferred;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000002"}',true);
select lives_ok($$insert into pg_temp.test_state values('marketing',public.register_file('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','b1000000-0000-4000-8000-000000000001','png',true))$$,'only an owner registers intentionally public marketing assets');
select lives_ok($$insert into storage.objects(bucket_id,name) select value->>'bucket',value->>'path' from pg_temp.test_state where key='marketing'$$,'registered marketing asset upload metadata accepted');
set local role anon;
select is((select count(*) from storage.objects where bucket_id='marketing-assets'),1::bigint,'intentional marketing metadata is public');
select is((select count(*) from storage.objects where bucket_id='client-files'),0::bigint,'public marketing grants do not expose private files');
reset role;
select is((select public from storage.buckets where id='client-files'),false,'client files bucket is private');
select is((select public from storage.buckets where id='marketing-assets'),true,'marketing bucket is intentionally public');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000002"}',true);
select lives_ok($$insert into pg_temp.test_state values('expired',public.issue_invitation('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','outsider@miznora.example.test','manager','all_locations','{}'))$$,'controlled invitation available for expiry test');
reset role;
update app_private.invitations set expires_at=now()-interval '1 second' where id=(select (value->>'id')::uuid from pg_temp.test_state where key='expired');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-000000000008"}',true);
select throws_ok($$select public.accept_invitation((select value->>'token' from pg_temp.test_state where key='expired'))$$,'42501',null,'expired invitation cannot grant membership');
select is((select count(*) from public.business_members where business_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1'),0::bigint,'expired invitation leaves no partial membership');
reset role;
select throws_ok($$insert into app_private.invitation_locations values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',(select (value->>'id')::uuid from pg_temp.test_state where key='expired'),'a1000000-0000-4000-8000-000000000001')$$,'23503',null,'invitation-location composite FK rejects another tenant invitation');
set constraints all immediate;
select * from finish();
rollback;
